#include "layer_norm_custom_tiling.h"
#include "register/op_def_registry.h"
#include "optiling/tiling_api.h"

namespace optiling {
static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    LayerNormCustomTilingData tiling;

    // 获取输入原始形状，按 [B, 1, H] 方式传给 LayerNorm Tiling，H=除 Batch 外的元素个数
    const gert::Shape* in_shape = context->GetInputShape(0);
    const auto& origin = in_shape->GetOriginShape();
    int64_t dim0 = 1;
    if (origin.GetDimNum() > 0) {
        dim0 = origin.GetDim(0);
    }
    uint64_t total_elems = origin.GetShapeSize();
    int64_t B = dim0;
    int64_t H = static_cast<int64_t>(total_elems / (B > 0 ? B : 1));
    // {B, S, storageHLength, originHLength}，此处 S=1，且不做 padding 对齐
    std::vector<int64_t> shape_vec = {B, 1, H, H};
    ge::Shape srcShape(shape_vec);

    uint32_t maxTmp = 0;
    uint32_t minTmp = 0;
    // 输入类型 float -> sizeof(float)=4
    AscendC::GetLayerNormMaxMinTmpSize(srcShape, sizeof(float), false, maxTmp, minTmp);
    AscendC::GetLayerNormNDTillingInfo(srcShape, minTmp, sizeof(float), false, tiling.layernormTilingData);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    // 无需 workspace
    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;
    context->SetTilingKey(1);
    return ge::GRAPH_SUCCESS;
}
}

namespace ge {
static ge::graphStatus InferShape(gert::InferShapeContext* context)
{
    // y 形状与 x 相同；mean/variance 为 [B, 1]
    const gert::Shape* x_shape = context->GetInputShape(0);
    const auto& origin = x_shape->GetOriginShape();

    int64_t dim0 = 1;
    if (origin.GetDimNum() > 0) {
        dim0 = origin.GetDim(0);
    }

    // 设置输出 y 形状
    gert::Shape* y_shape = context->GetOutputShape(0);
    *y_shape = *x_shape;

    // 设置 mean 与 variance 形状为 [B, 1]
    gert::Shape* mean_shape = context->GetOutputShape(1);
    gert::Shape* var_shape  = context->GetOutputShape(2);
    std::vector<int64_t> mv = {dim0, 1};
    mean_shape->SetDimNum(2);
    mean_shape->SetDim(0, mv[0]);
    mean_shape->SetDim(1, mv[1]);
    var_shape->SetDimNum(2);
    var_shape->SetDim(0, mv[0]);
    var_shape->SetDim(1, mv[1]);
    return GRAPH_SUCCESS;
}

static ge::graphStatus InferDataType(gert::InferDataTypeContext *context)
{
    const auto inputDataType = context->GetInputDataType(0);
    context->SetOutputDataType(0, inputDataType);
    context->SetOutputDataType(1, inputDataType);
    context->SetOutputDataType(2, inputDataType);
    return ge::GRAPH_SUCCESS;
}
}

