at::Tensor layer_norm_custom_impl_npu(const at::Tensor& x, const at::Tensor& gamma, const at::Tensor& beta) {
    at::Tensor y = at::empty_like(x);
    // mean/variance 输出形状 [B, 1]
    auto B = x.size(0);
    auto opts = x.options().dtype(at::kFloat);
    at::Tensor mean = at::empty({B, 1}, opts);
    at::Tensor variance = at::empty({B, 1}, opts);

    EXEC_NPU_CMD(aclnnLayerNormCustom, x, gamma, beta, y, mean, variance);
    return y;
}

