import torch
import torch_npu
import custom_ops_lib

class ModelNew(torch.nn.Module):
    """
    使用自定义 AscendC LayerNormCustom 内核替换 PyTorch LayerNorm。
    将最后 normalized_shape 维度展平为 H，按 [B, 1, H] 进行 LayerNorm 计算。
    """
    def __init__(self, normalized_shape: tuple):
        super().__init__()
        self.normalized_shape = tuple(normalized_shape)
        # 与 PyTorch nn.LayerNorm 的缺省初始化一致
        self.weight = torch.nn.Parameter(torch.ones(self.normalized_shape, dtype=torch.float))
        self.bias   = torch.nn.Parameter(torch.zeros(self.normalized_shape, dtype=torch.float))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        gamma = self.weight.reshape(-1).contiguous()
        beta  = self.bias.reshape(-1).contiguous()
        return custom_ops_lib.layer_norm_custom(x, gamma, beta)
